import re,glob,collections
order=['geography-routes','ecology-resources','history-periodisation','social-structure','power-systems','governance-law','economy-trade','faith-myth','language-names','daily-life','conflicts-tensions','want-vs-need','formative-past','relationships','contradictions','secrets','competence-failure','voice-attention']
files=sorted(glob.glob('encyclopedia/*.md'))
info={}
for f in files:
    t=open(f).read(); fm=t.split('---')[1]
    slug=f.split('/')[1][:-3]
    pil=[p.strip() for p in re.search(r'pillars:\s*\[([^\]]*)\]',fm).group(1).split(',')]
    kind=re.search(r'kind:\s*(\S+)',fm).group(1)
    body=t.split('## Canon')[1].split('## Open questions')[0]
    est=len([m for m in re.findall(r'^- established: .*',body,re.M) if 'supersedes' not in m])
    prop=len(re.findall(r'^- proposed:',body,re.M))
    info[slug]=dict(kind=kind,pil=pil,est=est,prop=prop,t=t)
inbound=collections.Counter()
for s,d in info.items():
    for m in re.findall(r'\[\[([^\]]+)\]\]',d['t'].split('## Links')[-1]):
        if m!=s: inbound[m]+=1
pill=collections.defaultdict(lambda: dict(e=set(),est=0,prop=0))
for s,d in info.items():
    for q in d['pil']:
        pill[q]['e'].add(s); pill[q]['est']+=d['est']; pill[q]['prop']+=d['prop']
rows={}
for k in order:
    n=len(pill[k]['e']); e=pill[k]['est']; p=pill[k]['prop']
    s='empty' if n==0 else ('all-proposed' if e==0 else ('thin' if e<3 else 'substantial'))
    rows[k]=f"| {k} | {n} | {e} | {p} | {s} |"
idx=open('index.md').read()
for k in order: idx=re.sub(r'^\| '+k+r' \|.*$', rows[k], idx, flags=re.M)
# entity rows: status + inbound hooks
for s,d in info.items():
    st='established' if d['est']>=3 and d['prop']==0 else ('mixed' if d['est'] and d['prop'] else ('proposed' if d['prop'] and not d['est'] else 'established'))
    line=f"| {s} | {d['kind']} | {', '.join(d['pil'])} | {st} | {inbound[s]} |"
    if re.search(r'^\| '+s+r' \|.*$', idx, flags=re.M):
        idx=re.sub(r'^\| '+s+r' \|.*$', line, idx, flags=re.M)
    else:
        idx=idx.rstrip('\n')+'\n'+line+'\n'
open('index.md','w').write(idx)
print('inbound hooks:',dict(inbound))
for k in order: print(rows[k])
